	_box(Vector3(1.55, 0.12, 0.14), Vector3(0, 1.6, 0.85), Color("#252a31"), 0.2)
	for x in [-1.0, 1.0]:
		for z in [-1.42, 1.42]:
			var wheel := _cylinder(0.43, 0.28, Vector3(x, 0.43, z), Color("#161a20"))
